(()=>{'use strict';
const $=s=>document.querySelector(s), act=$('#activity'), book=$('.book-shell'), turn=$('#turning');
const asset=name=>`assets/nuevos/${name}`, file=(n,s)=>`assets/paginas/${n===9?'moraleja1':`capitulo${n}`}-${s}.png`;
const maskedPages={"capitulo2-1.png":"data:image/svg+xml;base64,","capitulo5-1.png":"data:image/svg+xml;base64,","capitulo2-2.png":"data:image/svg+xml;base64,","capitulo1-2.png":"data:image/svg+xml;base64,","capitulo3-2.png":"data:image/svg+xml;base64,","capitulo6-1.png":"data:image/svg+xml;base64,","capitulo4-1.png":"data:image/svg+xml;base64,","actividad-derecha.png":"data:image/svg+xml;base64,","capitulo8-2.png":"data:image/svg+xml;base64,","capitulo7-2.png":"data:image/svg+xml;base64,","moraleja1-2.png":"data:image/svg+xml;base64,","capitulo5-2.png":"data:image/svg+xml;base64,","capitulo1-1.png":"data:image/svg+xml;base64,","capitulo3-1.png":"data:image/svg+xml;base64,","actividad-izquierda.png":"data:image/svg+xml;base64,","capitulo7-1.png":"data:image/svg+xml;base64,","capitulo6-2.png":"data:image/svg+xml;base64,","capitulo8-1.png":"data:image/svg+xml;base64,","moraleja1-1.png":"data:image/svg+xml;base64,","capitulo4-2.png":"data:image/svg+xml;base64,"};function setPageImage(el,src){el.src=src;const mask=maskedPages[src.split("/").pop()];el.style.maskImage=mask?`url("${mask}")`:"none";el.style.maskSize="100% 100%";el.style.maskRepeat="no-repeat";}
const activities=[
{after:2,kind:'sequence',title:'El comienzo de la aventura',instructions:'Toca una tarjeta y después otra para intercambiar sus lugares. Ordena las cuatro escenas de principio a fin.',example:'Primero, Karl inventa el automóvil.',cards:[['Karl inventa el automóvil','carta1.png'],['Bertha prepara un viaje','carta2.png'],['Bertha invita a sus hijos','carta3.png'],['Comienza la aventura','carta4.png']]},
{after:4,kind:'pairs',title:'Cada carta tiene una historia',instructions:'Selecciona una carta ilustrada y luego la descripción que le corresponde. Encuentra las cuatro parejas.',example:'Automóvil → Vehículo con motor.',cards:[['Automóvil','automobil.png','Vehículo con motor'],['Ligroína','ligroina.png','Producto que usaron como combustible'],['Farmacia','farmacia.png','Lugar donde compraron ligroína'],['Bertha','bertha.png','Protagonista del viaje']]},
{after:6,kind:'choice',title:'¿Qué utilizó Bertha?',instructions:'Mira las cartas y elige el objeto con el que Bertha limpió el tubo obstruido.',example:'Toca la carta del objeto correcto.',cards:[['Rueda','rueda.png'],['Alfiler','alfiler.png'],['Ligroína','ligroina.png']],answer:1},
{after:7,kind:'sentence',title:'Construye la oración',instructions:'Toca las palabras en el orden correcto para contar cómo ayudó el zapatero. Si te equivocas, podrás volver a intentarlo.',example:'Empieza con «El».',illustration:'zapato.png',cards:['El','zapatero','reparó','los','frenos']},
{after:8,kind:'sequence',title:'Recuerda el gran viaje',instructions:'Intercambia dos tarjetas cada vez hasta ordenar estos momentos de la aventura.',example:'Comienza con la salida de Bertha.',cards:[['Comienza el viaje','carta-1.png'],['Consiguen combustible','carta-2.png'],['Bertha resuelve un problema','carta-3.png'],['Llegan a su destino','carta-4.png']]}
];
const items=[];function buildItems(withActivities){items.length=0;for(let n=1;n<=9;n++){items.push({type:'chapter',n});const a=withActivities&&activities.find(a=>a.after===n);if(a)items.push({...a,type:'activity'});}}buildItems(true);
let readingMode='activities',started=false;const modeDialog=$('#readingModes');
let pos=0,busy=false,solved=true,timer,activityTimer,autoPlay=false,narrationPage=-1,token=0;
const narrator=$('#narrator'),bgm=$('#bgm'),narrate=$('#narrate'),vol=$('#volume');let fade;
bgm.src=$('#track').value;
function musicVolume(duck=false){cancelAnimationFrame(fade);let start=bgm.volume,target=Number(vol.value)/100*(duck?.22:1),t=performance.now();const step=now=>{let k=Math.min(1,(now-t)/450);bgm.volume=Math.max(0,Math.min(1,start+(target-start)*k));if(k<1)fade=requestAnimationFrame(step)};fade=requestAnimationFrame(step);}
function stopNarration(){clearTimeout(timer);token++;narrationPage=-1;narrator.pause();narrator.currentTime=0;narrate.textContent='▶ Escuchar capítulo';musicVolume();}
async function playNarration(){if(busy||!started||modeDialog.open||endDialog.open||items[pos].type!=='chapter')return;let myToken=++token;narrationPage=pos;clearTimeout(timer);narrator.pause();narrator.src=asset(items[pos].n===9?'moraleja.mp3':`capitulo${items[pos].n}.mp3`);try{await narrator.play();if(myToken===token){narrate.textContent='⏸ Pausar narración';musicVolume(true);}}catch(e){if(myToken===token){narrate.textContent='▶ Escuchar capítulo';musicVolume();}}}
narrator.onended=()=>{if(pos===items.length-1&&narrationPage===pos&&!busy){showEnd();return;}narrate.textContent='↻ Escuchar de nuevo';musicVolume();if(autoPlay&&!busy&&items[pos].type==='chapter'&&narrationPage===pos){if(pos<items.length-1)move(1);else{autoPlay=false;updateAutoButton();}}};narrator.onerror=()=>{narrate.textContent='▶ Reintentar narración';musicVolume()};
function resumeNarration(){if(busy||!started||modeDialog.open||endDialog.open||items[pos].type!=='chapter')return;clearTimeout(timer);if(!narrator.paused){narrator.pause();narrate.textContent='▶ Continuar narración';musicVolume();}else if(narrationPage===pos&&narrator.currentTime>0&&!narrator.ended){narrator.play().then(()=>{musicVolume(true);narrate.textContent='⏸ Pausar narración'}).catch(()=>{});}else playNarration();}
narrate.onclick=resumeNarration;
function updateAutoButton(){const b=$('#autoPlay');b.setAttribute('aria-pressed',String(autoPlay));b.textContent=autoPlay?'Auto: activada':'Auto: desactivada';b.title=autoPlay&&items[pos].type==='activity'?'Continúa al resolver o saltar la actividad':'Reproducción automática al terminar la narración';}
$('#autoPlay').onclick=()=>{autoPlay=!autoPlay;updateAutoButton();if(autoPlay&&!busy&&items[pos].type==='chapter'&&narrator.paused)resumeNarration();};
$('#musicToggle').onclick=async()=>{if(bgm.paused){try{await bgm.play();$('#musicToggle').textContent='♫ Música: activada';musicVolume(!narrator.paused)}catch(e){$('#musicToggle').textContent='♫ Activar música'}}else{bgm.pause();$('#musicToggle').textContent='♫ Música: desactivada'}};
vol.oninput=()=>musicVolume(!narrator.paused);$('#track').onchange=()=>{let playing=!bgm.paused;bgm.src=$('#track').value;if(playing)bgm.play().catch(()=>{});musicVolume(!narrator.paused)};musicVolume();
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b;}
function render(){$('#chooseMode').disabled=false;clearTimeout(activityTimer);const it=items[pos];updateAutoButton();book.classList.toggle('activity-mode',it.type==='activity');act.hidden=it.type!=='activity';$('#progress').textContent=`${pos+1} / ${items.length} · ${it.type==='activity'?'Actividad':it.n===9?'Moraleja':`Capítulo ${it.n}`}`;$('#prev').disabled=pos===0;$('#next').disabled=false;$('#next').setAttribute('aria-label',pos===items.length-1?'Finalizar historia':'Página siguiente');narrate.disabled=it.type==='activity';if(it.type==='chapter'){setPageImage($('#left'),file(it.n,1));setPageImage($('#right'),file(it.n,2));solved=true;narrate.textContent='▶ Escuchar capítulo'}else{setPageImage($('#left'),'assets/paginas/actividad-izquierda.png');setPageImage($('#right'),'assets/paginas/actividad-derecha.png');drawActivity(it);$('#next').disabled=true;}}
function drawActivity(it){
solved=false;let chosen=null,answer=null,words=[],done=new Set();const currentPos=pos;let order=shuffle(it.cards.map((c,i)=>({c,i})));if(order.every((x,i)=>x.i===i))order.reverse();
const sequence=it.kind==='sequence',pairs=it.kind==='pairs',sentence=it.kind==='sentence';
const leftTitle=sequence?'Ordena las tarjetas':pairs?'Une cada carta con su descripción':sentence?'Ordena la oración':'¿Con qué objeto limpió Bertha el tubo?';
const rightTitle=sequence?'Toca dos tarjetas para intercambiarlas':pairs?'Toca la descripción que corresponde':sentence?'Toca las palabras en orden':'Toca la respuesta correcta';
const details=sequence?'Coloca los hechos del primero al último.':pairs?'Elige una carta y busca su significado en la otra hoja.':sentence?'Recuerda cómo el zapatero ayudó a continuar el viaje.':'El tubo estaba obstruido y el combustible no podía pasar.';
const hint=sequence?it.example:pairs?'El automóvil es el vehículo con motor.':sentence?'Empieza con «El» y después elige quién realizó la acción.':'Era un objeto pequeño y puntiagudo del sombrero de Bertha.';
act.className=`activity-panel ${it.kind}-activity`;
const leftExtra=pairs?'':`<p class="activity-detail">${details}</p>`;
const rightExtra=sequence?'<p class="activity-detail">Revisa el orden del 1 al 4.</p>':'';
const sequenceActions='<div class="sequence-actions"><button id="check" type="button">Comprobar</button><button id="skip" type="button">Saltar actividad →</button></div>';
const hintBox=`<aside class="activity-hint"><strong>Pista</strong><p>${hint}</p></aside>`;
act.innerHTML=`<section class="paper-side paper-left"><div class="paper-content"><h2>${leftTitle}</h2>${leftExtra}${sequence||pairs?`<div id="leftCards" class="paper-cards ${sequence?'sequence':'pair-pictures'}"></div>`:''}${pairs?'':hintBox}${!sequence&&!pairs?'<p id="feedback" class="feedback" role="status"></p>':''}</div></section><section class="paper-side paper-right"><div class="paper-content"><p class="short-instruction">${rightTitle}</p>${rightExtra}${sentence?`<img class="helper-image" src="${asset(it.illustration)}" alt="Zapatero">`:''}<div id="rightCards" class="paper-cards ${it.kind}"></div>${sentence?'<p id="sentence" class="sentence-answer" aria-live="polite">…</p>':''}${sequence?`<div class="sequence-footer">${sequenceActions}<p id="feedback" class="feedback" role="status"></p></div>`:pairs?'<p id="feedback" class="feedback" role="status"></p>':''}</div></section>`;
if(!sequence){const skip=document.createElement('button');skip.type='button';skip.id='skip';skip.className='activity-skip';skip.textContent='Saltar actividad →';act.querySelector('.paper-right .paper-content').append(skip);}
const fx=window.BookSounds||{play(){},wrong(){},right(){}};
function feedback(message){$('#feedback').textContent=message;}
function succeed(){if(solved)return;solved=true;chosen=null;feedback('¡Muy bien! Continuamos en 5 segundos.');$('#next').disabled=false;act.classList.add('completed');act.querySelectorAll('button').forEach(b=>b.disabled=true);fx.play('success');clearTimeout(activityTimer);activityTimer=setTimeout(()=>{if(pos===currentPos&&solved&&!busy)move(1)},5000);}
function button(label,fn,cls='',img){let b=document.createElement('button');b.type='button';b.className=cls;b.setAttribute('aria-label',label);b.setAttribute('aria-pressed',String(cls.includes('selected')));if(img){let image=document.createElement('img');image.src=asset(img);image.alt=label;b.append(image);}else b.textContent=label;b.onclick=()=>{if(!solved)fn(b)};return b;}
function draw(){const left=$('#leftCards'),right=$('#rightCards');left?.replaceChildren();right.replaceChildren();
if(sequence)order.forEach((o,i)=>{let b=button(`${i+1}. ${o.c[0]}`,()=>{if(chosen===null){chosen=i;fx.play('select')}else{[order[i],order[chosen]]=[order[chosen],order[i]];chosen=null;fx.play('swap')}draw();if(order.every((o,i)=>o.i===i))succeed();},chosen===i?'selected':'',o.c[1]);b.dataset.position=i+1;const number=document.createElement('span');number.className='sequence-number';number.textContent=i+1;number.setAttribute('aria-hidden','true');b.prepend(number);(i<2?left:right).append(b)});
if(it.kind==='choice')it.cards.forEach((c,i)=>{right.append(button(c[0],()=>{answer=i;draw();if(i===it.answer)succeed();else{feedback('Prueba con otro objeto.');fx.wrong(right.querySelectorAll('button')[i])}},answer===i?'selected':'',c[1]))});
if(pairs){it.cards.forEach((c,i)=>{let b=button(c[0],()=>{chosen=i;feedback('Ahora toca su descripción.');fx.play('select');draw()},done.has(i)?'done':chosen===i?'selected':'',c[1]);b.dataset.pair=i;b.disabled=done.has(i);left.append(b)});order.forEach(o=>{let b=button(o.c[2],()=>{if(chosen===null){feedback('Elige primero una carta.');fx.wrong(b);return;}const selected=chosen;if(selected===o.i){done.add(o.i);chosen=null;feedback('¡Pareja correcta!');draw();if(done.size===it.cards.length)succeed();else fx.right(left.querySelector(`[data-pair="${selected}"]`),right.querySelector(`[data-pair="${o.i}"]`));}else{feedback('Esa pareja no corresponde. Prueba otra descripción.');fx.wrong(left.querySelector(`[data-pair="${selected}"]`),b);}},done.has(o.i)?'done':'');b.dataset.pair=o.i;b.disabled=done.has(o.i);right.append(b)})}
if(sentence){order.forEach(o=>{let b=button(o.c,()=>{fx.play('select');words.push(o.i);draw();if(words.length===it.cards.length){if(words.every((n,i)=>n===i))succeed();else{feedback('Intentémoslo de nuevo.');fx.wrong($('#sentence'));words=[];clearTimeout(activityTimer);activityTimer=setTimeout(()=>{if(pos===currentPos&&!busy&&!solved)draw()},1000)}}});b.disabled=words.includes(o.i);right.append(b)});$('#sentence').textContent=words.length?words.map(i=>it.cards[i]).join(' '):'…';}
}
act.classList.remove('completed');draw();
if(sequence){$('#check').onclick=()=>{if(order.every((o,i)=>o.i===i))succeed();else{feedback('Revisa los números y el orden de la historia.');fx.wrong(...act.querySelectorAll('.paper-cards button'));}};}
$('#skip').onclick=()=>{if(busy)return;solved=true;clearTimeout(activityTimer);move(1);fx.play('tap');};
}

function imageFor(it,s){return it.type==='chapter'?file(it.n,s):`assets/paginas/actividad-${s===1?'izquierda':'derecha'}.png`;}
function move(d){if(!started||modeDialog.open||$('#storyEnd').open)return;if(d>0&&pos===items.length-1&&!busy){showEnd();return;}let dest=pos+d;if(busy||dest<0||dest>=items.length||(d>0&&!solved))return;busy=true;$('#chooseMode').disabled=true;clearTimeout(activityTimer);stopNarration();window.BookSounds?.stop();const old=items[pos],next=items[dest];act.classList.add('during-turn');$('#prev').disabled=true;$('#next').disabled=true;const a=$(pos%2?'#turn1':'#turn2');for(const audio of [$('#turn1'),$('#turn2')]){audio.pause();audio.currentTime=0;}a.volume=.45;a.currentTime=0;a.play().catch(()=>{});turn.classList.remove('active','reverse');turn.style.display='block';turn.style.left=d>0?'50%':'0';turn.style.transformOrigin=d>0?'left center':'right center';setPageImage($('#turnFront'),imageFor(old,d>0?2:1));setPageImage($('#turnBack'),imageFor(next,d>0?1:2));let duration=matchMedia('(prefers-reduced-motion: reduce)').matches?100:1800;turn.style.setProperty('--flip-duration',`${duration}ms`);requestAnimationFrame(()=>requestAnimationFrame(()=>{turn.classList.add('active');if(d<0)turn.classList.add('reverse')}));setTimeout(()=>{setPageImage($('#left'),imageFor(next,1));setPageImage($('#right'),imageFor(next,2))},duration/2);setTimeout(()=>{turn.classList.remove('active','reverse');turn.style.display='none';act.classList.remove('during-turn');pos=dest;busy=false;render();if(items[pos].type==='chapter')playNarration()},duration+70);}
$('#prev').onclick=()=>move(-1);$('#next').onclick=()=>move(1);document.addEventListener('keydown',e=>{if(modeDialog.open||$('#storyEnd').open)return;if(['INPUT','SELECT','BUTTON'].includes(document.activeElement.tagName))return;if(e.key==='ArrowRight')move(1);if(e.key==='ArrowLeft')move(-1)});window.addEventListener('pagehide',()=>{clearTimeout(activityTimer);stopNarration();bgm.pause();$('#turn1').pause();$('#turn2').pause()});const endDialog=$('#storyEnd');
function stopAllAudio(){clearTimeout(timer);clearTimeout(activityTimer);stopNarration();cancelAnimationFrame(fade);bgm.pause();$('#musicToggle').textContent='♫ Música: desactivada';for(const a of [$('#turn1'),$('#turn2')]){a.pause();a.currentTime=0;}window.BookSounds?.stop();}
function showEnd(){if(busy||endDialog.open)return;stopAllAudio();autoPlay=false;updateAutoButton();endDialog.showModal();window.BookSounds?.play('finish');}
$('#endLibrary').addEventListener('click',stopAllAudio);
$('#closeEnd').onclick=()=>endDialog.close();
$('#restartStory').onclick=()=>startReading(readingMode);
function startReading(mode){stopAllAudio();readingMode=mode;started=true;autoPlay=false;buildItems(mode==='activities');pos=0;busy=false;solved=true;if(endDialog.open)endDialog.close();if(modeDialog.open)modeDialog.close();$('#chooseMode').textContent=mode==='story'?'Modo: Solo historia':'Modo: Con actividades';render();timer=setTimeout(playNarration,5000);}
modeDialog.querySelectorAll('[data-mode]').forEach(button=>button.onclick=()=>startReading(button.dataset.mode));
$('#chooseMode').onclick=()=>{if(busy)return;stopAllAudio();$('#keepReading').hidden=!started;modeDialog.showModal();};
$('#keepReading').onclick=()=>{modeDialog.close();if(items[pos].type==='activity'&&solved)activityTimer=setTimeout(()=>move(1),5000);};
modeDialog.addEventListener('cancel',e=>{if(!started)e.preventDefault();});
const stage=$('#bookStage');function fitBook(){const r=stage.getBoundingClientRect();book.style.width=Math.max(1,Math.floor(Math.min(r.width,r.height*25/9)))+'px';}if(window.ResizeObserver)new ResizeObserver(fitBook).observe(stage);window.addEventListener('resize',fitBook);fitBook();render();modeDialog.showModal();
})();
